SourceCode.Declaration:
/// <summary>
/// Table class for NVOrderLine - Employment order line records.
/// Each line represents one employee in an order and contains employment details.
/// </summary>
/// <remarks>
/// Relationships:
/// - Child of NVOrderHeader (via OrderHeaderRecId)
/// - Links to HcmWorker for employee data
/// - Links to HcmPosition for position information
/// - Links to OMOperatingUnit for department
///
/// Delete behavior:
/// - Table-level delete() is intentionally clean (only super()).
/// - UI business rule "cannot delete last line in consolidated order"
///   is enforced in NVOrderDetails.NVOrderLine_ds.validateDelete().
/// - Cascade delete from NVOrderHeader is handled via DeleteAction=Cascade (AOT).
///
/// Display methods provide formatted data for forms and reports.
/// </remarks>
public class NVOrderLine extends common
{
}

Method.Source:
// -------------------------------------------------------------------------
// Display methods
// -------------------------------------------------------------------------

/// <summary>
/// Display method that returns the employee's full name.
/// Navigates through HcmWorker to DirPerson.
/// </summary>
/// <returns>Employee name, or empty string if not found</returns>
public display Name displayEmployeeName()
{
    HcmWorker worker = HcmWorker::find(this.WorkerRecId);
    return worker.RecId ? DirPerson::find(worker.Person).Name : '';
}

/// <summary>
/// Display method that returns the employee's personnel number.
/// </summary>
/// <returns>Personnel number from HcmWorker</returns>
public display HcmPersonnelNumberId displayPersonnelNumber()
{
    return HcmWorker::find(this.WorkerRecId).PersonnelNumber;
}

/// <summary>
/// Display method that returns the employee's FIN (Financial Identification Number).
/// Retrieves the FIN from HcmPersonIdentificationNumber using the 'FIN' identification type.
/// </summary>
/// <returns>FIN string, or empty string if not found</returns>
public display HcmIdentificationNumber displayEmployeeFIN()
{
    HcmWorker                     worker = HcmWorker::find(this.WorkerRecId);
    HcmIdentificationType         idType;
    HcmPersonIdentificationNumber identNumber;

    if (worker.RecId)
    {
        select firstonly idType
            where idType.IdentificationTypeId == 'FIN';

        if (idType.RecId)
        {
            identNumber = HcmPersonIdentificationNumber::findByPersonAndType(
                worker.Person,
                idType.RecId);

            return identNumber.IdentificationNumber;
        }
    }

    return '';
}

/// <summary>
/// Display method that returns the department name.
/// Retrieves from OMOperatingUnit using DepartmentRecId.
/// </summary>
/// <returns>Department name, or 'N/A' if not found</returns>
public display Name displayDepartmentName()
{
    OMOperatingUnit department;

    if (!this.DepartmentRecId)
    {
        return 'N/A';
    }

    department = OMOperatingUnit::find(this.DepartmentRecId, OMOperatingUnitType::OMDepartment);

    return department.RecId ? department.Name : 'N/A';
}

/// <summary>
/// Display method that returns the position description.
/// Retrieves localized description from HcmPositionDetail with fallback to PositionId.
/// </summary>
/// <returns>Position description, PositionId, or 'N/A' if not found</returns>
/// <remarks>
/// Priority: PositionDetail.Description (localized) -> Position.PositionId -> 'N/A'
/// </remarks>
public display Description displayPositionDescription()
{
    HcmPosition       position;
    HcmPositionDetail positionDetail;

    if (!this.PositionRecId)
    {
        return 'N/A';
    }

    position = HcmPosition::find(this.PositionRecId);

    if (!position.RecId)
    {
        return 'N/A';
    }

    // Get localized description from PositionDetail
    select firstonly Description from positionDetail
        where positionDetail.Position == position.RecId;

    return positionDetail.Description ? positionDetail.Description : position.PositionId;
}

// -------------------------------------------------------------------------
// Table overrides
// -------------------------------------------------------------------------

/// <summary>
/// Override delete.
/// Kept clean intentionally - no business logic here.
/// UI validation (last line in consolidated order) lives in
/// NVOrderDetails.NVOrderLine_ds.validateDelete().
/// Cascade from NVOrderHeader is handled by DeleteAction=Cascade in AOT.
/// </summary>
public void delete()
{
    super();
}

// -------------------------------------------------------------------------
// Static find methods
// -------------------------------------------------------------------------

/// <summary>
/// Finds an NVOrderLine record by RecId.
/// </summary>
/// <param name="_recId">RecId of the order line to find</param>
/// <param name="_forUpdate">If true, selects the record for update</param>
/// <returns>NVOrderLine record, or empty record if not found</returns>
public static NVOrderLine find(RecId _recId, boolean _forUpdate = false)
{
    NVOrderLine line;

    if (!_recId)
    {
        return line;
    }

    if (_forUpdate)
    {
        line.selectForUpdate(_forUpdate);
    }

    select firstonly line
        where line.RecId == _recId;

    return line;
}
